162	\toprule
163	\textbf{Comparison} & \textbf{$\Delta$ (pp)} & \textbf{95\% CI} & \textbf{$p$} \\
164	\midrule
165	Embed vs.\ Random & +0.4 & [$-$1.8, +2.6] & 0.34 \\
166	Dataflow vs.\ Random & $-$0.3 & [$-$2.5, +1.9] & 0.41 \\
